{"path": "sgf_parsing.py", "content": "class SgfTree:
    def __init__(self, properties=None, children=None):
        self.properties = properties or {}
        self.children = children or []

    def __eq__(self, other):
        if not isinstance(other, SgfTree):
            return False
        for key, value in self.properties.items():
            if key not in other.properties:
                return False
            if other.properties[key] != value:
                return False
        for key in other.properties.keys():
            if key not in self.properties:
                return False
        if len(self.children) != len(other.children):
            return False
        for child, other_child in zip(self.children, other.children):
            if child != other_child:
                return False
        return True

    def __ne__(self, other):
        return not self == other


def parse(input_string):
    s = input_string
    if not s or s[0] != "(" or s[-1] != ")":
        raise ValueError("tree missing")
    if len(s) < 2 or s[1] != ";":
        raise ValueError("tree with no nodes")
    tree, pos = _parse_tree(s, 0)
    if pos != len(s):
        raise ValueError("tree missing")
    return tree


def _parse_tree(s, pos):
    # s[pos] == "("
    pos += 1
    if pos >= len(s) or s[pos] != ";":
        raise ValueError("tree with no nodes")
    nodes = []
    while pos < len(s) and s[pos] == ";":
        props, pos = _parse_node(s, pos + 1)
        nodes.append(SgfTree(props))
    children = []
    while pos < len(s) and s[pos] == "(":
        child, pos = _parse_tree(s, pos)
        children.append(child)
    if pos >= len(s) or s[pos] != ")":
        raise ValueError("tree missing")
    nodes[-1].children = children
    for parent, child in zip(nodes, nodes[1:]):
        parent.children = [child]
    return nodes[0], pos + 1


def _parse_node(s, pos):
    props = {}
    while pos < len(s) and s[pos] not in ";()":
        start = pos
        while pos < len(s) and s[pos].isalpha():
            pos += 1
        key = s[start:pos]
        if not key:
            raise ValueError("properties without delimiter")
        if not key.isupper():
            raise ValueError("property must be in uppercase")
        if pos >= len(s) or s[pos] != "[":
            raise ValueError("properties without delimiter")
        values = []
        while pos < len(s) and s[pos] == "[":
            value, pos = _parse_value(s, pos + 1)
            values.append(value)
        props[key] = values
    return props, pos


def _parse_value(s, pos):
    out = []
    while pos < len(s):
        c = s[pos]
        if c == "]":
            return "".join(out), pos + 1
        if c == "\\":
            pos += 1
            if pos >= len(s):
                break
            c = s[pos]
            if c == "\n":
                pos += 1
                continue
        if c != "\n" and c.isspace():
            c = " "
        out.append(c)
        pos += 1
    raise ValueError("properties without delimiter")
